HERO_STR_STATIC(hero_str_1256, "unterminated_char");
HERO_STR_STATIC(hero_str_1257, "this character literal never closes \342\200\224 write one character between single quotes: 'a'");
HERO_STR_STATIC(hero_str_1258, "escape the backslash: `'\\\\'`");
